  // ====================================================================== RANKED
  // Queue entry: mp-ranked/queue/<key> = {k,n,ch,mode,ts,lv,rk}
  // Match record: mp-ranked/matches/<id> = {a:{key,name},b:{key,name},mode,code,ts}
  // Both clients listen to their own queue node; when a second player claims a
  // waiting entry, the FIRST of the two to commit the match document hosts.
  var RANKED = X.ranked = { state: 'idle', mode: 'coin', pair: null, onStop: null, opp: null };
  var chanQ = null, chanQFn = null;
  function chan() {
    if (chanQ) return chanQ;
    try { chanQ = new BroadcastChannel('ssmp-ranked'); } catch (e) { chanQ = null; }
    return chanQ;
  }
